/**
 * CMS Service Core — shared-utils
 *
 * DB-agnostic orchestration service. Owns domain rules (validation,
 * sanitization, concurrency, password hashing) and delegates persistence
 * to a CmsConnector.
 */
import { nanoid } from "nanoid";
import type { CmsConnector, CmsConnectorWithPublicHead } from "./connector.js";
import { hasPublicHead } from "./connector.js";
import type {
  CmsHeadRow,
  CmsHistoryRow,
  CmsListRequest,
  CmsListResponse,
  CmsCreateRequest,
  CmsUpdateRequest,
  CmsPublicPayload,
  CmsAfterWriteEvent,
  CmsCollaboratorRow,
  CmsPublicHead,
  CmsMetadata,
} from "../../../utils/src/cms/types.js";
import {
  CmsCreateRequestSchema,
  CmsUpdateRequestSchema,
  CmsListRequestSchema,
  CmsMetadataSchema,
} from "../../../utils/src/cms/types.js";
import {
  CmsNotFoundError,
  CmsConflictError,
  CmsLockedError,
  CmsValidationError,
} from "../../../utils/src/cms/errors.js";
import {
  normalizeLocale,
  canonicalizeSlug,
  assertValidSlug,
  assertAllowedContentType,
  assertAllowedPostType,
} from "../../../utils/src/cms/validation.js";
import {
  assertIfMatchSatisfied,
  computeCmsEtag,
} from "../../../utils/src/cms/concurrency.js";
import { hashCmsPassword } from "./password.js";
import {
  sanitizeCmsHtml,
  renderMarkdownToSanitizedHtml,
} from "./sanitization.js";

// ─── Configuration ────────────────────────────────────────────────────────

export interface CmsServiceCoreConfig {
  /** The DB connector implementation. */
  connector: CmsConnector;
  /** Slugs that cannot be used (e.g., "admin", "api", "auth"). */
  reservedSlugs?: string[];
  /** Optional callback fired after write operations. */
  onAfterWrite?: (event: CmsAfterWriteEvent) => Promise<void>;
  /** Lock TTL in milliseconds (default: 10 minutes). */
  lockTtlMs?: number;
}

// ─── Default lock TTL ─────────────────────────────────────────────────────

const DEFAULT_LOCK_TTL_MS = 10 * 60 * 1000; // 10 minutes
const CMS_MAX_LIST_LIMIT = 200;

const clampCmsListLimit = (value: number | undefined): number | undefined => {
  if (value === undefined) {
    return undefined;
  }
  return Math.min(CMS_MAX_LIST_LIMIT, Math.max(1, Math.floor(value)));
};

const clampCmsOffset = (value: number | undefined): number | undefined => {
  if (value === undefined) {
    return undefined;
  }
  return Math.max(0, Math.floor(value));
};

// ─── Service ──────────────────────────────────────────────────────────────

export class CmsServiceCore {
  private connector: CmsConnector;
  private reservedSlugs: string[];
  private onAfterWrite?: (event: CmsAfterWriteEvent) => Promise<void>;
  private lockTtlMs: number;

  constructor(config: CmsServiceCoreConfig) {
    this.connector = config.connector;
    this.reservedSlugs = config.reservedSlugs || [];
    this.onAfterWrite = config.onAfterWrite;
    this.lockTtlMs = config.lockTtlMs ?? DEFAULT_LOCK_TTL_MS;
  }

  // ─── List ─────────────────────────────────────────────────────────────

  async list(params: CmsListRequest): Promise<CmsListResponse> {
    const parsed = CmsListRequestSchema.parse({
      ...params,
      limit: clampCmsListLimit(params.limit),
      offset: clampCmsOffset(params.offset),
    });
    return this.connector.list(parsed);
  }

  // ─── Get by UID ───────────────────────────────────────────────────────

  async getByUid(uid: string): Promise<CmsHeadRow> {
    const row = await this.connector.getByUid(uid);
    if (!row) {
      throw new CmsNotFoundError(`CMS item not found: ${uid}`);
    }
    return row;
  }

  // ─── Create ───────────────────────────────────────────────────────────

  async create(input: {
    request: CmsCreateRequest;
    actorUserUid?: string | null;
  }): Promise<CmsHeadRow> {
    const parsed = CmsCreateRequestSchema.parse(input.request);

    const locale = normalizeLocale(parsed.locale);
    const slug = canonicalizeSlug(parsed.slug);
    assertValidSlug(slug, this.reservedSlugs);
    assertAllowedContentType(parsed.content_type);
    assertAllowedPostType(parsed.post_type);

    const uid = parsed.uid || nanoid(21);
    const version = 1;
    const etag = computeCmsEtag(uid, version);
    const now = new Date().toISOString();

    let passwordHash: string | null = null;
    let passwordVersion = 0;
    if (parsed.password) {
      passwordHash = await hashCmsPassword(parsed.password);
      passwordVersion = 1;
    }

    const row = await this.connector.insert({
      uid,
      userUid: input.actorUserUid || null,
      title: parsed.title,
      content: parsed.content ?? "",
      content_type: parsed.content_type,
      slug,
      locale,
      post_type: parsed.post_type,
      options: parsed.options ?? null,
      metadata: this.stampMetadataUserUid(
        parsed.metadata ?? {},
        input.actorUserUid,
      ),
      tags: parsed.tags ?? null,
      password_hash: passwordHash,
      password_version: passwordVersion,
      status: "draft",
      etag,
      version_number: version,
      created_at: now,
      updated_at: now,
    });

    await this.fireAfterWrite({
      type: "create",
      uid,
      row,
      actorUserUid: input.actorUserUid,
    });

    return row;
  }

  // ─── Update ───────────────────────────────────────────────────────────

  async updateByUid(input: {
    uid: string;
    patch: CmsUpdateRequest;
    ifMatchHeader: string | null | undefined;
    actorUserUid?: string | null;
  }): Promise<CmsHeadRow> {
    const parsed = CmsUpdateRequestSchema.parse(input.patch);

    const current = await this.connector.getByUid(input.uid);
    if (!current) {
      throw new CmsNotFoundError(`CMS item not found: ${input.uid}`);
    }

    // Concurrency check
    assertIfMatchSatisfied({
      ifMatchHeader: input.ifMatchHeader,
      currentEtag: current.etag,
    });

    // Build patch
    const dbPatch: Partial<CmsHeadRow> = {};
    const now = new Date().toISOString();

    if (parsed.title !== undefined) {
      dbPatch.title = parsed.title;
    }
    if (parsed.content !== undefined) {
      dbPatch.content = parsed.content;
    }
    if (parsed.content_type !== undefined) {
      assertAllowedContentType(parsed.content_type);
      dbPatch.content_type = parsed.content_type;
    }
    if (parsed.locale !== undefined) {
      dbPatch.locale = normalizeLocale(parsed.locale);
    }
    if (parsed.post_type !== undefined) {
      assertAllowedPostType(parsed.post_type);
      dbPatch.post_type = parsed.post_type;
    }
    if (parsed.options !== undefined) {
      dbPatch.options = parsed.options;
    }
    if (parsed.metadata !== undefined) {
      dbPatch.metadata = this.stampMetadataUserUid(
        parsed.metadata,
        input.actorUserUid,
      );
    }
    if (parsed.tags !== undefined) {
      dbPatch.tags = parsed.tags;
    }

    // Slug change on published content requires confirmation
    if (parsed.slug !== undefined) {
      const newSlug = canonicalizeSlug(parsed.slug);
      assertValidSlug(newSlug, this.reservedSlugs);

      if (
        current.status === "published" &&
        newSlug !== current.slug &&
        !parsed.confirmSlugChange
      ) {
        throw new CmsConflictError(
          "Slug change on published content requires confirmSlugChange: true",
        );
      }
      dbPatch.slug = newSlug;
    }

    // Password update
    if (parsed.password !== undefined) {
      const hash = await hashCmsPassword(parsed.password);
      dbPatch.password_hash = hash;
      dbPatch.password_version = (current.password_version ?? 0) + 1;
    }

    // Bump version + etag
    const newVersion = (current.version_number ?? 0) + 1;
    dbPatch.version_number = newVersion;
    dbPatch.etag = computeCmsEtag(input.uid, newVersion);
    dbPatch.updated_at = now;

    // Best-effort history snapshot before update
    await this.createHistorySnapshot(current);

    const updated = await this.connector.updateByUid(input.uid, dbPatch);
    if (!updated) {
      throw new CmsNotFoundError(
        `CMS item not found after update: ${input.uid}`,
      );
    }

    await this.fireAfterWrite({
      type: "update",
      uid: input.uid,
      row: updated,
      actorUserUid: input.actorUserUid,
    });

    return updated;
  }

  // ─── Publish ──────────────────────────────────────────────────────────

  async publishByUid(input: {
    uid: string;
    publishedAt?: string;
    ifMatchHeader: string | null | undefined;
    actorUserUid?: string | null;
  }): Promise<CmsHeadRow> {
    const current = await this.connector.getByUid(input.uid);
    if (!current) {
      throw new CmsNotFoundError(`CMS item not found: ${input.uid}`);
    }

    assertIfMatchSatisfied({
      ifMatchHeader: input.ifMatchHeader,
      currentEtag: current.etag,
    });

    const now = new Date().toISOString();
    const publishedAt = input.publishedAt || now;
    const newVersion = (current.version_number ?? 0) + 1;

    // Best-effort history snapshot
    await this.createHistorySnapshot(current);

    const patch: Partial<CmsHeadRow> = {
      status: "published",
      published_at: publishedAt,
      first_published_at: current.first_published_at || publishedAt,
      version_number: newVersion,
      etag: computeCmsEtag(input.uid, newVersion),
      updated_at: now,
    };

    const updated = await this.connector.updateByUid(input.uid, patch);
    if (!updated) {
      throw new CmsNotFoundError(`CMS item not found: ${input.uid}`);
    }

    await this.fireAfterWrite({
      type: "publish",
      uid: input.uid,
      row: updated,
      actorUserUid: input.actorUserUid,
    });

    return updated;
  }

  // ─── Trash ────────────────────────────────────────────────────────────

  async trashByUid(input: {
    uid: string;
    ifMatchHeader: string | null | undefined;
    actorUserUid?: string | null;
  }): Promise<CmsHeadRow> {
    const current = await this.connector.getByUid(input.uid);
    if (!current) {
      throw new CmsNotFoundError(`CMS item not found: ${input.uid}`);
    }

    assertIfMatchSatisfied({
      ifMatchHeader: input.ifMatchHeader,
      currentEtag: current.etag,
    });

    const now = new Date().toISOString();
    const newVersion = (current.version_number ?? 0) + 1;

    // Best-effort history snapshot
    await this.createHistorySnapshot(current);

    const patch: Partial<CmsHeadRow> = {
      status: "trash",
      trashed_at: now,
      trashed_by: input.actorUserUid || null,
      version_number: newVersion,
      etag: computeCmsEtag(input.uid, newVersion),
      updated_at: now,
    };

    const updated = await this.connector.updateByUid(input.uid, patch);
    if (!updated) {
      throw new CmsNotFoundError(`CMS item not found: ${input.uid}`);
    }

    await this.fireAfterWrite({
      type: "trash",
      uid: input.uid,
      row: updated,
      actorUserUid: input.actorUserUid,
    });

    return updated;
  }

  // ─── Restore ──────────────────────────────────────────────────────────

  async restoreByUid(input: {
    uid: string;
    ifMatchHeader: string | null | undefined;
    actorUserUid?: string | null;
  }): Promise<CmsHeadRow> {
    const current = await this.connector.getByUid(input.uid);
    if (!current) {
      throw new CmsNotFoundError(`CMS item not found: ${input.uid}`);
    }

    assertIfMatchSatisfied({
      ifMatchHeader: input.ifMatchHeader,
      currentEtag: current.etag,
    });

    const now = new Date().toISOString();
    const newVersion = (current.version_number ?? 0) + 1;

    // Best-effort history snapshot
    await this.createHistorySnapshot(current);

    const patch: Partial<CmsHeadRow> = {
      status: "draft",
      trashed_at: null,
      trashed_by: null,
      version_number: newVersion,
      etag: computeCmsEtag(input.uid, newVersion),
      updated_at: now,
    };

    const updated = await this.connector.updateByUid(input.uid, patch);
    if (!updated) {
      throw new CmsNotFoundError(`CMS item not found: ${input.uid}`);
    }

    await this.fireAfterWrite({
      type: "restore",
      uid: input.uid,
      row: updated,
      actorUserUid: input.actorUserUid,
    });

    return updated;
  }

  // ─── Delete (permanent) ───────────────────────────────────────────────

  /**
   * Permanently delete a CMS item. Enforces trash-first precondition:
   * the item must have status === "trash" before permanent deletion.
   */
  async deleteByUid(input: {
    uid: string;
    actorUserUid?: string | null;
  }): Promise<void> {
    const current = await this.connector.getByUid(input.uid);
    if (!current) {
      throw new CmsNotFoundError(`CMS item not found: ${input.uid}`);
    }

    if (current.status !== "trash") {
      throw new CmsValidationError(
        "Item must be trashed before permanent deletion",
        { status: "Item status must be 'trash' to delete permanently" },
      );
    }

    await this.connector.deleteByUid(input.uid);

    await this.fireAfterWrite({
      type: "delete",
      uid: input.uid,
      actorUserUid: input.actorUserUid,
    });
  }

  // ─── Empty trash ──────────────────────────────────────────────────────

  /**
   * Permanently delete all trashed items (up to limit).
   * Fires onAfterWrite({ type: "delete" }) for each item.
   */
  async emptyTrash(input?: {
    limit?: number;
    actorUserUid?: string | null;
  }): Promise<{ deletedCount: number; failedCount: number }> {
    const limit = Math.min(Math.max(input?.limit ?? 100, 1), 500);

    const result = await this.connector.list({
      status: "trash",
      limit,
      offset: 0,
    });

    let deletedCount = 0;
    let failedCount = 0;
    for (const item of result.items) {
      try {
        await this.connector.deleteByUid(item.uid);
        deletedCount++;

        await this.fireAfterWrite({
          type: "delete",
          uid: item.uid,
          actorUserUid: input?.actorUserUid,
        });
      } catch {
        failedCount++;
      }
    }

    return { deletedCount, failedCount };
  }

  // ─── Lock ─────────────────────────────────────────────────────────────

  async lockByUid(input: {
    uid: string;
    actorUserUid: string;
  }): Promise<CmsHeadRow> {
    const current = await this.connector.getByUid(input.uid);
    if (!current) {
      throw new CmsNotFoundError(`CMS item not found: ${input.uid}`);
    }

    // Check for existing lock by another user
    if (current.locked_by && current.locked_by !== input.actorUserUid) {
      // Check if the lock has expired
      if (current.locked_at) {
        const lockedAt = new Date(current.locked_at).getTime();
        const now = Date.now();
        if (now - lockedAt < this.lockTtlMs) {
          throw new CmsLockedError(
            "Content is locked by another user",
            current.locked_by,
            current.locked_at,
          );
        }
      }
    }

    const now = new Date().toISOString();
    const updated = await this.connector.updateByUid(input.uid, {
      locked_by: input.actorUserUid,
      locked_at: now,
    });

    if (!updated) {
      throw new CmsNotFoundError(`CMS item not found: ${input.uid}`);
    }

    return updated;
  }

  // ─── Unlock ───────────────────────────────────────────────────────────

  async unlockByUid(input: {
    uid: string;
    actorUserUid: string;
    force?: boolean;
  }): Promise<CmsHeadRow> {
    const current = await this.connector.getByUid(input.uid);
    if (!current) {
      throw new CmsNotFoundError(`CMS item not found: ${input.uid}`);
    }

    // Only the lock owner or force can unlock
    if (
      current.locked_by &&
      current.locked_by !== input.actorUserUid &&
      !input.force
    ) {
      throw new CmsLockedError(
        "Cannot unlock: locked by another user",
        current.locked_by,
        current.locked_at ?? undefined,
      );
    }

    const updated = await this.connector.updateByUid(input.uid, {
      locked_by: null,
      locked_at: null,
    });

    if (!updated) {
      throw new CmsNotFoundError(`CMS item not found: ${input.uid}`);
    }

    return updated;
  }

  // ─── History: list ────────────────────────────────────────────────────

  async listHistory(params: {
    cmsUid: string;
    limit?: number;
    offset?: number;
    includeSoftDeleted?: boolean;
  }): Promise<{ items: CmsHistoryRow[]; totalCount: number }> {
    return this.connector.listHistory({
      cmsUid: params.cmsUid,
      limit: clampCmsListLimit(params.limit) ?? 50,
      offset: clampCmsOffset(params.offset) ?? 0,
      includeSoftDeleted: params.includeSoftDeleted,
    });
  }

  // ─── History: restore revision ────────────────────────────────────────

  /**
   * Restore a history revision to the head row.
   * Creates a snapshot of the current state first, then applies
   * the history snapshot to the head row.
   */
  async restoreHistoryRevision(input: {
    cmsUid: string;
    historyId: number;
    ifMatchHeader: string | null | undefined;
    actorUserUid?: string | null;
  }): Promise<CmsHeadRow> {
    const current = await this.connector.getByUid(input.cmsUid);
    if (!current) {
      throw new CmsNotFoundError(`CMS item not found: ${input.cmsUid}`);
    }

    assertIfMatchSatisfied({
      ifMatchHeader: input.ifMatchHeader,
      currentEtag: current.etag,
    });

    const historyRow = await this.connector.getHistoryById(input.historyId);
    if (!historyRow || historyRow.cms_uid !== input.cmsUid) {
      throw new CmsNotFoundError(
        `History revision not found: ${input.historyId}`,
      );
    }

    const snapshot = historyRow.snapshot as Record<string, unknown> | null;
    if (!snapshot || typeof snapshot !== "object") {
      throw new CmsValidationError("Invalid history snapshot");
    }

    // Create history snapshot of current state first
    await this.createHistorySnapshot(current);

    const now = new Date().toISOString();
    const newVersion = (current.version_number ?? 0) + 1;

    // Apply snapshot fields to head row
    const patch: Partial<CmsHeadRow> = {
      title: snapshot.title as string | undefined,
      content: snapshot.content as string | undefined,
      content_type: snapshot.content_type as any,
      slug: snapshot.slug as string | undefined,
      locale: snapshot.locale as string | undefined,
      post_type: snapshot.post_type as any,
      options: snapshot.options,
      metadata: snapshot.metadata ?? null,
      tags: snapshot.tags as string[] | null | undefined,
      version_number: newVersion,
      etag: computeCmsEtag(input.cmsUid, newVersion),
      updated_at: now,
    };

    const updated = await this.connector.updateByUid(input.cmsUid, patch);
    if (!updated) {
      throw new CmsNotFoundError(`CMS item not found: ${input.cmsUid}`);
    }

    await this.fireAfterWrite({
      type: "history_restore",
      uid: input.cmsUid,
      row: updated,
      actorUserUid: input.actorUserUid,
    });

    return updated;
  }

  // ─── History: soft-delete ─────────────────────────────────────────────

  async softDeleteHistoryRevision(input: {
    historyId: number;
    actorUserUid?: string | null;
  }): Promise<CmsHistoryRow> {
    const row = await this.connector.getHistoryById(input.historyId);
    if (!row) {
      throw new CmsNotFoundError(
        `History revision not found: ${input.historyId}`,
      );
    }

    const updated = await this.connector.updateHistoryById(input.historyId, {
      soft_deleted_at: new Date().toISOString(),
      soft_deleted_by: input.actorUserUid || null,
    });

    if (!updated) {
      throw new CmsNotFoundError(
        `History revision not found: ${input.historyId}`,
      );
    }

    return updated;
  }

  // ─── History: hard-delete ─────────────────────────────────────────────

  async hardDeleteHistoryRevision(historyId: number): Promise<void> {
    const row = await this.connector.getHistoryById(historyId);
    if (!row) {
      throw new CmsNotFoundError(`History revision not found: ${historyId}`);
    }

    await this.connector.deleteHistoryById(historyId);
  }

  // ─── Collaborators ────────────────────────────────────────────────────

  async listCollaborators(cmsUid: string): Promise<CmsCollaboratorRow[]> {
    return this.connector.listCollaborators(cmsUid);
  }

  async replaceCollaborators(
    cmsUid: string,
    collaborators: Array<{ user_uid: string; role: string }>,
  ): Promise<CmsCollaboratorRow[]> {
    // Verify the CMS item exists
    const current = await this.connector.getByUid(cmsUid);
    if (!current) {
      throw new CmsNotFoundError(`CMS item not found: ${cmsUid}`);
    }

    return this.connector.replaceCollaborators(cmsUid, collaborators);
  }

  // ─── Public payload ───────────────────────────────────────────────────

  async getPublicPayloadBySlug(params: {
    postType: string;
    locale: string;
    slug: string;
  }): Promise<CmsPublicPayload | null> {
    const row = await this.connector.getPublishedBySlug(params);
    if (!row) {
      return null;
    }

    return this.renderPublicPayload(row);
  }

  /**
   * Render a safe payload for previewing a CMS item by UID.
   * Intended for authenticated preview flows (e.g., draft previews).
   */
  async getPreviewPayloadByUid(uid: string): Promise<CmsPublicPayload | null> {
    const row = await this.connector.getByUid(uid);
    if (!row) {
      return null;
    }
    return this.renderPublicPayload(row);
  }

  // ─── Public head (lightweight) ────────────────────────────────────────

  async getPublicHead(params: {
    postType: string;
    locale: string;
    slug: string;
  }): Promise<CmsPublicHead | null> {
    if (hasPublicHead(this.connector)) {
      return (this.connector as CmsConnectorWithPublicHead).getPublicHeadBySlug(
        params,
      );
    }

    // Fallback: full row read, derive head data
    const row = await this.connector.getPublishedBySlug(params);
    if (!row) {
      return null;
    }

    return {
      uid: row.uid,
      post_type: row.post_type ?? params.postType,
      locale: row.locale ?? params.locale,
      slug: row.slug ?? params.slug,
      status: row.status ?? "published",
      etag: row.etag ?? null,
      version_number: row.version_number ?? null,
      password_hash: row.password_hash ?? null,
      password_version: row.password_version ?? null,
      published_at: row.published_at ?? null,
      archived_at: row.archived_at ?? null,
    };
  }

  // ─── Internal helpers ─────────────────────────────────────────────────

  /**
   * Render a CMS head row into a safe public payload.
   * Sanitizes HTML, renders markdown, parses JSON.
   */
  private async renderPublicPayload(
    row: CmsHeadRow,
  ): Promise<CmsPublicPayload> {
    const payload: CmsPublicPayload = {
      uid: row.uid,
      post_type: row.post_type!,
      locale: row.locale!,
      slug: row.slug!,
      title: row.title ?? "",
      tags: row.tags,
      content_type: row.content_type!,
      published_at: row.published_at,
      updated_at: row.updated_at,
      options: row.options,
    };

    const content = row.content ?? "";

    switch (row.content_type) {
      case "text/html":
        payload.sanitized_html = sanitizeCmsHtml(content);
        break;
      case "text/markdown":
        payload.markdown_html = await renderMarkdownToSanitizedHtml(content);
        break;
      case "application/json":
        try {
          payload.json = content ? JSON.parse(content) : null;
        } catch {
          payload.json = null;
        }
        break;
      case "text/plain":
        payload.text = content;
        break;
    }

    return payload;
  }

  /**
   * Best-effort: create a history snapshot of the current state.
   * Errors are caught and logged but not propagated.
   */
  private async createHistorySnapshot(row: CmsHeadRow): Promise<void> {
    try {
      const snapshot = this.buildHistorySnapshot(row);
      await this.connector.insertHistory({
        cms_uid: row.uid,
        revision: row.version_number ?? 0,
        snapshot,
        created_by: row.userUid || null,
      });
    } catch (err) {
      // Best-effort: log but don't propagate
      if (typeof globalThis !== "undefined" && (globalThis as any).log) {
        (globalThis as any).log.warn("CMS history snapshot failed:", err);
      }
    }
  }

  // ─── Metadata: lightweight update (no snapshot, no version bump) ────

  /**
   * Update only the metadata column of a CMS item without creating a
   * history snapshot or bumping the version/etag. Used for adding
   * content notes or editing version annotations independently of
   * content saves.
   */
  async updateMetadataByUid(input: {
    uid: string;
    metadata: unknown;
    actorUserUid?: string | null;
  }): Promise<CmsHeadRow> {
    const current = await this.connector.getByUid(input.uid);
    if (!current) {
      throw new CmsNotFoundError(`CMS item not found: ${input.uid}`);
    }

    // Validate metadata shape (lenient — accept partial structures)
    const safeMeta =
      input.metadata && typeof input.metadata === "object"
        ? input.metadata
        : {};

    // Stamp user_uid on version meta and content notes
    const stampedMeta = this.stampMetadataUserUid(safeMeta, input.actorUserUid);

    const updated = await this.connector.updateByUid(input.uid, {
      metadata: stampedMeta,
      updated_at: new Date().toISOString(),
    });

    if (!updated) {
      throw new CmsNotFoundError(
        `CMS item not found after update: ${input.uid}`,
      );
    }

    return updated;
  }

  // ─── History: update version metadata on a snapshot ─────────────────

  /**
   * Annotate a history revision with version metadata (version label
   * and/or notes). Modifies the snapshot JSON in-place without
   * affecting the head row.
   */
  async updateHistoryVersionMeta(input: {
    historyId: number;
    version?: string | null;
    notes?: string | null;
    actorUserUid?: string | null;
  }): Promise<CmsHistoryRow> {
    const row = await this.connector.getHistoryById(input.historyId);
    if (!row) {
      throw new CmsNotFoundError(
        `History revision not found: ${input.historyId}`,
      );
    }

    const snapshot = (row.snapshot as Record<string, unknown> | null) ?? {};
    const existingMeta =
      (snapshot.metadata as Record<string, unknown> | null) ?? {};

    // Build updated version meta — null out if both fields empty
    const hasVersion = input.version != null && input.version.trim() !== "";
    const hasNotes = input.notes != null && input.notes.trim() !== "";

    const versionMeta =
      hasVersion || hasNotes
        ? {
            version: hasVersion ? input.version!.trim() : null,
            notes: hasNotes ? input.notes!.trim() : null,
            dt_updated: new Date().toISOString(),
            user_uid: input.actorUserUid || null,
          }
        : null;

    const updatedSnapshot = {
      ...snapshot,
      metadata: {
        ...existingMeta,
        version: versionMeta,
      },
    };

    const updated = await this.connector.updateHistoryById(input.historyId, {
      snapshot: updatedSnapshot,
    });

    if (!updated) {
      throw new CmsNotFoundError(
        `History revision not found: ${input.historyId}`,
      );
    }

    return updated;
  }

  /**
   * Stamp `user_uid` on metadata.version and any metadata.notes entries
   * that do not already have a `user_uid`. Mutates a shallow copy.
   */
  private stampMetadataUserUid(
    metadata: unknown,
    actorUserUid?: string | null,
  ): Record<string, unknown> {
    if (!metadata || typeof metadata !== "object") {
      return {};
    }
    const meta = { ...(metadata as Record<string, unknown>) };
    const uid = actorUserUid || null;

    // Stamp version meta
    if (meta.version && typeof meta.version === "object") {
      const versionMeta = meta.version as Record<string, unknown>;
      meta.version = {
        ...versionMeta,
        ...(Object.prototype.hasOwnProperty.call(versionMeta, "user_uid")
          ? {}
          : { user_uid: uid }),
      };
    }

    // Stamp notes entries that do not define user_uid at all.
    if (Array.isArray(meta.notes)) {
      meta.notes = meta.notes.map((n: unknown) => {
        if (n && typeof n === "object") {
          const note = n as Record<string, unknown>;

          if (!Object.prototype.hasOwnProperty.call(note, "user_uid")) {
            return { ...note, user_uid: uid };
          }

          return { ...note };
        }

        return n;
      });
    }

    return meta;
  }

  /**
   * Build a snapshot object from a CMS head row for history storage.
   */
  private buildHistorySnapshot(row: CmsHeadRow): Record<string, unknown> {
    return {
      uid: row.uid,
      title: row.title ?? "",
      content: row.content ?? "",
      content_type: row.content_type ?? null,
      slug: row.slug ?? null,
      locale: row.locale ?? null,
      post_type: row.post_type ?? null,
      options: row.options ?? null,
      metadata: row.metadata ?? null,
      tags: row.tags ?? null,
      status: row.status ?? null,
      etag: row.etag ?? null,
      version_number: row.version_number ?? null,
      updated_at: row.updated_at ?? null,
      published_at: row.published_at ?? null,
      first_published_at: row.first_published_at ?? null,
      password_version: row.password_version ?? null,
    };
  }

  private async fireAfterWrite(event: CmsAfterWriteEvent): Promise<void> {
    if (!this.onAfterWrite) {
      return;
    }
    try {
      await this.onAfterWrite(event);
    } catch (err) {
      if (typeof globalThis !== "undefined" && (globalThis as any).log) {
        (globalThis as any).log.warn("CMS onAfterWrite hook error:", err);
      }
    }
  }
}
